  examples = $cr8eDBf85C$[{"input": "100\n40 49 90 12 68 63 67 95 23 6 21 0 79 73 66 99 80 69 60 96 42 4 89 67 8 11 28 73 68 42 44 47 20 77 88 86 64 69 39 35 78 66 61 95 74 3 51 98 50 21 83 31 5 21 34 8 97 93 42 8 58 47 59 16 97 90 30 82 ...", "output": "0 3 3 4 4 5 6 8 8 8 8 9 10 10 10 11 12 16 16 17 20 21 21 21 21 21 23 25 28 30 31 33 34 35 39 40 42 42 42 42 44 47 47 49 50 50 51 54 57 58 59 59 60 61 61 63 63 64 64 66 66 67 67 68 68 68 69 69 73 73 73..."}]$cr8eDBf85C$::jsonb,
  solutions = $cr262bD4e1${"typescript": "// 小根堆排序：建小根堆后依次弹出，得到升序序列。\nimport * as readline from 'readline';\n\nfunction solve(input: string): string {\n  const data = input.trim().split(/\\s+/).map(Number);\n  if (data.length === 0) return '';\n  const n = data[0];\n  const a: number[] = data.slice(1, 1 + n);\n  // 简易二叉堆\n  const heap: number[] = [];\n  const swap = (i: number, j: number) => { [heap[i], heap[j]] = [heap[j], heap[i]]; };\n  const shiftUp = (i: number) => {\n    while (i > 0) {\n      const p = (i - 1) >> 1;\n      if (heap[p] <= heap[i]) break;\n      swap(i, p); i = p;\n    }\n  };\n  const shiftDown = (i: number, size: number) => {\n    while (i * 2 + 1 < size) {\n      let j = i * 2 + 1;\n      if (j + 1 < size && heap[j + 1] < heap[j]) j++;\n      if (heap[j] >= heap[i]) break;\n      swap(i, j); i = j;\n    }\n  };\n  for (const x of a) { heap.push(x); shiftUp(heap.length - 1); }\n  const out: string[] = [];\n  for (let k = 0; k < n; k++) {\n    out.push(String(heap[0]));\n    heap[0] = heap[heap.length - 1]; heap.pop();\n    shiftDown(0, heap.length);\n  }\n  return out.join(' ');\n}\n\n// 本地运行入口（Node）：node heap.ts < input.txt\nif (require.main === module) {\n  let buf = '';\n  process.stdin.on('data', d => buf += d);\n  process.stdin.on('end', () => console.log(solve(buf)));\n}\n", "python": "# 小根堆排序：读入 n 个数，建小根堆后依次弹出，得到升序序列。\nimport sys, heapq\n\ndef main():\n    data = sys.stdin.read().split()\n    if not data:\n        return\n    n = int(data[0])\n    a = list(map(int, data[1:1 + n]))\n    heapq.heapify(a)            # 原地建小根堆 O(n)\n    out = [str(heapq.heappop(a)) for _ in range(n)]  # 每次取最小 O(log n)\n    print(' '.join(out))\n\nif __name__ == '__main__':\n    main()\n", "java": "import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        if (!sc.hasNextInt()) return;\n        int n = sc.nextInt();\n        int[] a = new int[n];\n        for (int i = 0; i < n; i++) a[i] = sc.nextInt();\n        PriorityQueue<Integer> pq = new PriorityQueue<>();\n        for (int x : a) pq.offer(x);\n        StringBuilder sb = new StringBuilder();\n        while (!pq.isEmpty()) sb.append(pq.poll()).append(' ');\n        System.out.println(sb.toString().trim());\n    }\n}\n"}$cr262bD4e1$::jsonb,
